#include <bits/stdc++.h>
using namespace std;

#define x first
#define y second
#define mp make_pair
#define pb push_back
#define sz(a) int((a).size())
#define forn(i, n) for(int i = 0; i < int(n); ++i)
#define fore(i, l, r) for(int i = int(l); i < int(r); ++i)

typedef long long li;
typedef pair<int, int> pt;

const int MOD = 1000000007;
const int MAX_K = 32;

li n;
int k;

bool read_input() {
    return scanf("%lld%d", &n, &k) == 2;
}

inline int add(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

inline int mul(int a, int b) {
    return (long long)a * b % MOD;
}

using Matrix = array<array<int, MAX_K>, MAX_K>;

Matrix multiply(const Matrix& A, const Matrix& B) {
    Matrix C;
    forn(i, k + 1) forn(j, k + 1) C[i][j] = 0;
    forn(i, k + 1) forn(j, k + 1) forn(t, k + 1)
        C[i][j] = add(C[i][j], mul(A[i][t], B[t][j]));
    return C;
}

Matrix base_matrices[62][MAX_K];

void process() {
    vector<int> digits;
    li temp = n;
    while (temp > 0) {
        digits.push_back(temp % k);
        temp /= k;
    }

    forn(d, k) {
        forn(i, k + 1) forn(j, k + 1) base_matrices[0][d][i][j] = 0;
        forn(i, k + 1) base_matrices[0][d][i][i] = 1;
        forn(i, k + 1) base_matrices[0][d][i][d] = 1;
    }

    fore(level, 1, sz(digits)) {
        vector<Matrix> prefix;
        prefix.emplace_back();
        forn(i, k + 1) forn(j, k + 1) prefix[0][i][j] = (i == j ? 1 : 0);
        forn(i, k) prefix.push_back(multiply(prefix.back(), base_matrices[level - 1][i]));

        forn(shift, k) {
            base_matrices[level][shift] = prefix[0];
            forn(i, k - shift)
                base_matrices[level][shift] = multiply(base_matrices[level][shift], base_matrices[level - 1][(i + shift) % k]);
            base_matrices[level][shift] = multiply(base_matrices[level][shift], prefix[shift]);
        }
    }

    Matrix dp;
    forn(i, k + 1) forn(j, k + 1) dp[i][j] = 0;
    dp[0][k] = 1;

    int remainder = 0;
    for (int i = sz(digits) - 1; i >= 0; --i) {
        while (digits[i] > 0) {
            dp = multiply(dp, base_matrices[i][remainder]);
            remainder = (remainder + 1) % k;
            --digits[i];
        }
    }

    int result = 0;
    forn(i, k + 1) result = add(result, dp[0][i]);
    printf("%d\n", result);
}

int main() {
#ifdef _DEBUG
    freopen("input.txt", "r", stdin);
#endif

    while (read_input()) {
        process();
    }
    return 0;
}
